    { const char * tb_v439 = "// ядро процессора («звезда»): его номер, кого он сейчас ведёт, свой стек для пустого хода.\n"; *(const char * *)tb_grow(v_lines) = tb_v439; }
    { const char * tb_v440 = "// Регистр GS у каждого ядра смотрит на его запись (в самом начале — адрес её самой)\n"; *(const char * *)tb_grow(v_lines) = tb_v440; }
    { const char * tb_v441 = "#define TB_NCPU 16\n"; *(const char * *)tb_grow(v_lines) = tb_v441; }
    { const char * tb_v442 = "typedef struct tb_cpu_s {\n"; *(const char * *)tb_grow(v_lines) = tb_v442; }
