    { const char * tb_v451 = "TB_API int tb_ncpu = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v451; }
    { const char * tb_v452 = "TB_INL tb_cpu *tb_me(void) { tb_cpu *c; __asm__ volatile(\"movq %%gs:0, %0\" : \"=r\"(c)); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v452; }
    { const char * tb_v453 = "// короткое дело библиотеки (память, экран, список задач): прерывания выключены и взят общий\n"; *(const char * *)tb_grow(v_lines) = tb_v453; }
    { const char * tb_v454 = "// замок — так его не делят ни прерывание, ни другое ядро процессора. Можно вкладывать\n"; *(const char * *)tb_grow(v_lines) = tb_v454; }
    { const char * tb_v455 = "TB_API volatile int tb_bkl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v455; }
