    { const char * tb_v561 = "TB_API void tb_vga_font(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v561; }
    { const char * tb_v562 = "    tb_outw(0x3C4, 0x0402); tb_outw(0x3C4, 0x0704);   // пишем в слой шрифта\n"; *(const char * *)tb_grow(v_lines) = tb_v562; }
    { const char * tb_v563 = "    tb_outw(0x3CE, 0x0204); tb_outw(0x3CE, 0x0005); tb_outw(0x3CE, 0x0406);\n"; *(const char * *)tb_grow(v_lines) = tb_v563; }
    { const char * tb_v564 = "    volatile unsigned char *font = (volatile unsigned char *)0xA0000;\n"; *(const char * *)tb_grow(v_lines) = tb_v564; }
    { const char * tb_v565 = "    for (int i = 0; i < 66; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v565; }
