    { const char * tb_v567 = "    tb_outw(0x3C4, 0x0302); tb_outw(0x3C4, 0x0304);   // обратно в текстовый режим\n"; *(const char * *)tb_grow(v_lines) = tb_v567; }
    { const char * tb_v568 = "    tb_outw(0x3CE, 0x0004); tb_outw(0x3CE, 0x1005); tb_outw(0x3CE, 0x0E06);\n"; *(const char * *)tb_grow(v_lines) = tb_v568; }
    { const char * tb_v569 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v569; }
    { const char * tb_v570 = "TB_API unsigned char tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v570; }
    { const char * tb_v571 = "TB_API void tb_putc(char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v571; }
    { const char * tb_v572 = "    unsigned char ch = (unsigned char)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v572; }
    { const char * tb_v573 = "    while ((tb_inb(0x3F8 + 5) & 0x20) == 0) {}\n"; *(const char * *)tb_grow(v_lines) = tb_v573; }
    { const char * tb_v574 = "    tb_outb(0x3F8, ch);   // в порт — как есть (UTF-8)\n"; *(const char * *)tb_grow(v_lines) = tb_v574; }
    { const char * tb_v575 = "    if (ch < 0x80) { tb_utf_lead = 0; tb_vga_put(ch); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v575; }
    { const char * tb_v576 = "    if (ch >= 0xC0) { tb_utf_lead = ch; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v576; }
    { const char * tb_v577 = "    // второй байт: А..я = U+0410..U+044F, Ё = U+0401, ё = U+0451\n"; *(const char * *)tb_grow(v_lines) = tb_v577; }
    { const char * tb_v578 = "    unsigned cp = ((unsigned)(tb_utf_lead & 0x1F) << 6) | (ch & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v578; }
    { const char * tb_v579 = "    if (tb_utf_lead == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v579; }
    { const char * tb_v580 = "    tb_utf_lead = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v580; }
    { const char * tb_v581 = "    if (cp >= 0x410 && cp <= 0x44F) tb_vga_put((unsigned char)(128 + cp - 0x410));\n"; *(const char * *)tb_grow(v_lines) = tb_v581; }
    { const char * tb_v582 = "    else if (cp == 0x401) tb_vga_put(128 + 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v582; }
    { const char * tb_v583 = "    else if (cp == 0x451) tb_vga_put(128 + 65);\n"; *(const char * *)tb_grow(v_lines) = tb_v583; }
    { const char * tb_v584 = "    else tb_vga_put('?');\n"; *(const char * *)tb_grow(v_lines) = tb_v584; }
    { const char * tb_v585 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v585; }
    { const char * tb_v586 = "// строка не рвётся: пока задача не дописала свою строку до '\\n', другие ждут (недолго —\n"; *(const char * *)tb_grow(v_lines) = tb_v586; }
    { const char * tb_v587 = "// если задача так и не допишет, через ~20 мс пишут всё равно)\n"; *(const char * *)tb_grow(v_lines) = tb_v587; }
    { const char * tb_v588 = "TB_API volatile long long tb_line_owner = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v588; }
    { const char * tb_v589 = "TB_API long long tb_out_me(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v589; }
    { const char * tb_v590 = "TB_API int fputs(const char *s, FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v590; }
    { const char * tb_v591 = "    if (!*s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v591; }
    { const char * tb_v592 = "    long long me = tb_out_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v592; }
    { const char * tb_v593 = "    uint64_t fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v593; }
    { const char * tb_v594 = "    for (long spins = 0;; spins++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v594; }
    { const char * tb_v595 = "        fl = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v595; }
    { const char * tb_v596 = "        long long o = tb_line_owner;\n"; *(const char * *)tb_grow(v_lines) = tb_v596; }
    { const char * tb_v597 = "        if (o == 0 || o == me || me < 0 || spins > 4000000) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v597; }
    { const char * tb_v598 = "        tb_irq_restore(fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v598; }
    { const char * tb_v599 = "        __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v599; }
    { const char * tb_v600 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v600; }
    { const char * tb_v601 = "    unsigned char was = tb_vcolor;\n"; *(const char * *)tb_grow(v_lines) = tb_v601; }
    { const char * tb_v602 = "    if (f == stderr) tb_vcolor = 0x0C;   // ошибки — красным\n"; *(const char * *)tb_grow(v_lines) = tb_v602; }
    { const char * tb_v603 = "    char last = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v603; }
    { const char * tb_v604 = "    while (*s) { last = *s; tb_putc(*s++); }\n"; *(const char * *)tb_grow(v_lines) = tb_v604; }
    { const char * tb_v605 = "    tb_vcolor = was;\n"; *(const char * *)tb_grow(v_lines) = tb_v605; }
    { const char * tb_v606 = "    if (me >= 0) tb_line_owner = last == '\\n' ? 0 : me;\n"; *(const char * *)tb_grow(v_lines) = tb_v606; }
    { const char * tb_v607 = "    tb_irq_restore(fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v607; }
    { const char * tb_v608 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v608; }
    { const char * tb_v609 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v609; }
    { const char * tb_v610 = "TB_API int fflush(FILE *f) { (void)f; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v610; }
    { const char * tb_v611 = "TB_API int isatty(int fd) { (void)fd; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v611; }
    { const char * tb_v612 = "TB_API char *getenv(const char *n) { (void)n; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v612; }
    { const char * tb_v613 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v613; }
    { const char * tb_v614 = "// выход: QEMU с -device isa-debug-exit закрывается, без него процессор просто спит\n"; *(const char * *)tb_grow(v_lines) = tb_v614; }
    { const char * tb_v615 = "__attribute__((noreturn)) static void exit(int code) {\n"; *(const char * *)tb_grow(v_lines) = tb_v615; }
    { const char * tb_v616 = "    tb_outb(0xF4, (unsigned char)code);\n"; *(const char * *)tb_grow(v_lines) = tb_v616; }
    { const char * tb_v617 = "    for (;;) __asm__ volatile(\"cli; hlt\");\n"; *(const char * *)tb_grow(v_lines) = tb_v617; }
    { const char * tb_v618 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v618; }
    { const char * tb_v619 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v619; }
    { const char * tb_v620 = "// память: запас 64 МБ. Куски по размерам 16, 32, 64, ... байт; отданный кусок\n"; *(const char * *)tb_grow(v_lines) = tb_v620; }
    { const char * tb_v621 = "// кладётся в корзину своего размера и выдаётся снова. Последний кусок отдаётся сразу.\n"; *(const char * *)tb_grow(v_lines) = tb_v621; }
    { const char * tb_v622 = "#define TB_HEAP (64 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v622; }
    { const char * tb_v623 = "TB_API unsigned char tb_heap[TB_HEAP] __attribute__((aligned(16), section(\".tbheap\")));\n"; *(const char * *)tb_grow(v_lines) = tb_v623; }
    { const char * tb_v624 = "TB_API size_t tb_heap_top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v624; }
    { const char * tb_v625 = "TB_API void *tb_bins[32];\n"; *(const char * *)tb_grow(v_lines) = tb_v625; }
    { const char * tb_v626 = "// заголовок куска: размер (номер 4..31) + метка «это начало куска» — так по адресу видно,\n"; *(const char * *)tb_grow(v_lines) = tb_v626; }
    { const char * tb_v627 = "// наш ли это кусок (для передачи владения), и хозяин (клетка) рядом\n"; *(const char * *)tb_grow(v_lines) = tb_v627; }
    { const char * tb_v628 = "#define TB_HMAGIC 0x0B1A0C0000000000ull\n"; *(const char * *)tb_grow(v_lines) = tb_v628; }
    { const char * tb_v629 = "#define TB_TAG_FREE (~0ull)\n"; *(const char * *)tb_grow(v_lines) = tb_v629; }
    { const char * tb_v630 = "// запас памяти (как зона Service в старой Омниум): последние 8 МБ кучи берут только ядро,\n"; *(const char * *)tb_grow(v_lines) = tb_v630; }
    { const char * tb_v631 = "// прерывания и службы. Обычные клетки упираются раньше — и службы живут, даже когда клетки съели всё\n"; *(const char * *)tb_grow(v_lines) = tb_v631; }
    { const char * tb_v632 = "#define TB_RESERVE (8 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v632; }
    { const char * tb_v633 = "TB_API size_t tb_heap_limit(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v633; }
    { const char * tb_v634 = "TB_API int tb_cls(size_t n) { int k = 4; while (k < 31 && ((size_t)1 << k) < n) k++; return k; }\n"; *(const char * *)tb_grow(v_lines) = tb_v634; }
    { const char * tb_v635 = "TB_API void *tb_malloc0(size_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v635; }
    { const char * tb_v636 = "    int k = tb_cls(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v636; }
    { const char * tb_v637 = "    if (tb_bins[k]) { void *p = tb_bins[k]; tb_bins[k] = *(void **)p; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v637; }
    { const char * tb_v638 = "    size_t need = ((size_t)1 << k) + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v638; }
    { const char * tb_v639 = "    if (tb_heap_top + need > tb_heap_limit()) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v639; }
    { const char * tb_v640 = "    unsigned char *h = tb_heap + tb_heap_top;\n"; *(const char * *)tb_grow(v_lines) = tb_v640; }
    { const char * tb_v641 = "    *(size_t *)h = (size_t)k | TB_HMAGIC;\n"; *(const char * *)tb_grow(v_lines) = tb_v641; }
    { const char * tb_v642 = "    tb_heap_top += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v642; }
    { const char * tb_v643 = "    return h + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v643; }
    { const char * tb_v644 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v644; }
    { const char * tb_v645 = "TB_API void tb_free0(void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v645; }
    { const char * tb_v646 = "    if (p == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v646; }
    { const char * tb_v647 = "    unsigned char *h = (unsigned char *)p - 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v647; }
    { const char * tb_v648 = "    int k = (int)(*(size_t *)h & 0xFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v648; }
    { const char * tb_v649 = "    if (h + ((size_t)1 << k) + 16 == tb_heap + tb_heap_top) { tb_heap_top = (size_t)(h - tb_heap); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v649; }
    { const char * tb_v650 = "    *(void **)p = tb_bins[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v650; }
    { const char * tb_v651 = "    tb_bins[k] = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v651; }
    { const char * tb_v652 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v652; }
    { const char * tb_v653 = "// квота клетки: каждый кусок помнит хозяина (в заголовке, за размером); у клетки — счёт байт.\n"; *(const char * *)tb_grow(v_lines) = tb_v653; }
    { const char * tb_v654 = "// Клетка, взявшая больше своей квоты, падает одна (main и прерывания без квоты)\n"; *(const char * *)tb_grow(v_lines) = tb_v654; }
    { const char * tb_v655 = "#define TB_CELL_QUOTA (16 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v655; }
    { const char * tb_v656 = "TB_API uint64_t tb_cell_charge(size_t bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v656; }
    { const char * tb_v657 = "TB_API void tb_cell_refund(uint64_t tag, long long bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v657; }
    { const char * tb_v658 = "TB_API int tb_cell_fits(uint64_t tag, long long more);\n"; *(const char * *)tb_grow(v_lines) = tb_v658; }
    { const char * tb_v659 = "__attribute__((noreturn)) TB_API void tb_cell_fall(const char *what, int line);\n"; *(const char * *)tb_grow(v_lines) = tb_v659; }
    { const char * tb_v660 = "TB_API int tb_cell_can_fall(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v660; }
