    { const char * tb_v662 = "TB_API void tb_mem_soft(int d);\n"; *(const char * *)tb_grow(v_lines) = tb_v662; }
    { const char * tb_v663 = "TB_API size_t tb_piece(void *p) { return (size_t)1 << (*(size_t *)((unsigned char *)p - 16) & 0xFF); }\n"; *(const char * *)tb_grow(v_lines) = tb_v663; }
