    { const char * tb_v1012 = "    int no;                               // номер клетки: по порядку запуска (1, 2, 3 ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v1012; }
    { const char * tb_v1013 = "    uint64_t gen; long long mem;          // поколение слота (для хозяина кусков) и байты клетки\n"; *(const char * *)tb_grow(v_lines) = tb_v1013; }
    { const char * tb_v1014 = "    int *locks[8]; int nlocks;            // замки, которые клетка держит сейчас\n"; *(const char * *)tb_grow(v_lines) = tb_v1014; }
    { const char * tb_v1015 = "    int svc;                              // служба (a = service f()): ей можно в запас памяти\n"; *(const char * *)tb_grow(v_lines) = tb_v1015; }
    { const char * tb_v1016 = "    int soft;                             // сейчас new_mem / grow_mem: нет памяти — ошибка, а не падение\n"; *(const char * *)tb_grow(v_lines) = tb_v1016; }
    { const char * tb_v1017 = "    unsigned char tls[TB_TLS_MAX + 16] __attribute__((aligned(16)));   // блок переменных потока + адрес самого себя\n"; *(const char * *)tb_grow(v_lines) = tb_v1017; }
    { const char * tb_v1018 = "} tb_kslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v1018; }
