    { const char * tb_v1020 = "TB_API unsigned char tb_tstacks[TB_NTASK][TB_TSTACK] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v1020; }
    { const char * tb_v1021 = "TB_API int tb_nlive = 1, tb_cell_count = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1021; }
    { const char * tb_v1022 = "// своё у каждой задачи (переменные потока): номер её слота; у функций прерывания tb_in_irq = 1\n"; *(const char * *)tb_grow(v_lines) = tb_v1022; }
