    { const char * tb_v1044 = "TB_INL void *tb_tls_self(void) { void *p; __asm__ volatile(\"movq %%fs:0, %0\" : \"=r\"(p)); return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1044; }
    { const char * tb_v1045 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v1045; }
    { const char * tb_v1046 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1046; }
    { const char * tb_v1047 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1047; }
    { const char * tb_v1048 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v1048; }
    { const char * tb_v1049 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1049; }
    { const char * tb_v1050 = "    s->mem += (long long)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v1050; }
    { const char * tb_v1051 = "    return (uint64_t)tb_cur | (s->gen << 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1051; }
    { const char * tb_v1052 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1052; }
    { const char * tb_v1053 = "// new_mem / grow_mem просят память «мягко»: не хватило — ответ else err, клетка живёт\n"; *(const char * *)tb_grow(v_lines) = tb_v1053; }
    { const char * tb_v1054 = "TB_API int tb_mem_soft_now(void) { return !tb_in_irq && tb_slots[tb_cur].soft > 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1054; }
    { const char * tb_v1055 = "TB_API void tb_mem_soft(int d) { if (!tb_in_irq) tb_slots[tb_cur].soft += d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1055; }
    { const char * tb_v1056 = "TB_API size_t tb_heap_limit(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1056; }
    { const char * tb_v1057 = "    if (tb_in_irq || tb_cur == 0 || tb_slots[tb_cur].svc) return TB_HEAP;\n"; *(const char * *)tb_grow(v_lines) = tb_v1057; }
    { const char * tb_v1058 = "    return TB_HEAP - TB_RESERVE;\n"; *(const char * *)tb_grow(v_lines) = tb_v1058; }
    { const char * tb_v1059 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1059; }
    { const char * tb_v1060 = "// хватит ли клетке квоты, если её кусок вырастет на месте (иначе растём через malloc — он и уронит)\n"; *(const char * *)tb_grow(v_lines) = tb_v1060; }
    { const char * tb_v1061 = "TB_API int tb_cell_fits(uint64_t tag, long long more) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1061; }
    { const char * tb_v1062 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1062; }
    { const char * tb_v1063 = "    if (i == 0 || i >= TB_NTASK || tb_slots[i].gen != (tag >> 8)) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1063; }
    { const char * tb_v1064 = "    return tb_slots[i].mem + more <= TB_CELL_QUOTA;\n"; *(const char * *)tb_grow(v_lines) = tb_v1064; }
    { const char * tb_v1065 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1065; }
    { const char * tb_v1066 = "TB_API void tb_cell_refund(uint64_t tag, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1066; }
    { const char * tb_v1067 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1067; }
    { const char * tb_v1068 = "    if (i >= TB_NTASK || tb_slots[i].gen != (tag >> 8) || !tb_slots[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1068; }
    { const char * tb_v1069 = "    tb_slots[i].mem -= bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v1069; }
    { const char * tb_v1070 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1070; }
    { const char * tb_v1071 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1071; }
    { const char * tb_v1072 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1072; }
    { const char * tb_v1073 = "TB_API void tb_irq_set(int v, void (*fn)(void)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1073; }
    { const char * tb_v1074 = "    tb_irq_fn[v - 32] = fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v1074; }
    { const char * tb_v1075 = "    tb_pic_mask &= (uint16_t)~(1u << (v - 32));\n"; *(const char * *)tb_grow(v_lines) = tb_v1075; }
    { const char * tb_v1076 = "    if (v >= 40) tb_pic_mask &= (uint16_t)~(1u << 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v1076; }
