    { const char * tb_v1081 = "TB_API void tb_yield(void) { if (!tb_in_irq) __asm__ volatile(\"int $48\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1081; }
    { const char * tb_v1082 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1082; }
    { const char * tb_v1083 = "// переключение задач: запомнить кадр и «переменные потока» текущей, отдать кадр следующей\n"; *(const char * *)tb_grow(v_lines) = tb_v1083; }
    { const char * tb_v1084 = "TB_API uint64_t *tb_schedule(uint64_t *frame) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1084; }
    { const char * tb_v1085 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v1085; }
    { const char * tb_v1086 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v1086; }
    { const char * tb_v1087 = "    int cur = c->run;\n"; *(const char * *)tb_grow(v_lines) = tb_v1087; }
    { const char * tb_v1088 = "    if (cur >= 0) tb_slots[cur].frame = frame; else c->idle_frame = frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v1088; }
    { const char * tb_v1089 = "    // следующая по кругу: живая и не идущая на другом ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v1089; }
    { const char * tb_v1090 = "    int n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1090; }
    { const char * tb_v1091 = "    for (int k = 1; k <= TB_NTASK; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1091; }
    { const char * tb_v1092 = "        int j = ((cur < 0 ? 0 : cur) + k) % TB_NTASK;\n"; *(const char * *)tb_grow(v_lines) = tb_v1092; }
    { const char * tb_v1093 = "        tb_kslot *s = &tb_slots[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v1093; }
