    { const char * tb_v2312 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v2312; }
    { const char * tb_v2313 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v2313; }
