    { const char * tb_v2541 = "TB_API double tb_gnow(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec * 1e3 + ts.tv_nsec / 1e6; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2541; }
    { const char * tb_v2542 = "TB_API void tb_gc_collect(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2542; }
