    { const char * tb_v2824 = "TB_INL long long tb_tlen(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "    if (tb_lc_p[0] == s) return tb_lc_n[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
