    { const char * tb_v2831 = "// ---------- буквы: len, s[i], cut, find, code, char и each считают буквы, а не байты ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2831; }
    { const char * tb_v2832 = "// Текст хранится в UTF-8: латинская буква — 1 байт, русская — 2, иероглиф — 3, смайлик — 4.\n"; *(const char * *)tb_grow(v_lines) = tb_v2832; }
    { const char * tb_v2833 = "// Байт, который не складывается в букву (испорченный UTF-8, байты с диска), — сам себе буква.\n"; *(const char * *)tb_grow(v_lines) = tb_v2833; }
    { const char * tb_v2834 = "TB_INL long long tb_u8n(const unsigned char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2834; }
    { const char * tb_v2835 = "    unsigned char b = p[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v2835; }
    { const char * tb_v2836 = "    if (b < 0xC2 || b > 0xF4) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2836; }
    { const char * tb_v2837 = "    long long need = b < 0xE0 ? 2 : b < 0xF0 ? 3 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "    for (long long k = 1; k < need; k++) if ((p[k] & 0xC0) != 0x80) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "    return need;\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "// сколько букв в первых nb байтах\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "TB_API long long tb_u8count(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
    { const char * tb_v2843 = "    const unsigned char *p = (const unsigned char *)s, *e = p + nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v2843; }
    { const char * tb_v2844 = "    long long n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2844; }
    { const char * tb_v2845 = "    while (p < e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2845; }
    { const char * tb_v2846 = "        if (*p < 0x80) { p++; n++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2846; }
    { const char * tb_v2847 = "        long long k = tb_u8n(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
    { const char * tb_v2848 = "        if (p + k > e) k = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2848; }
    { const char * tb_v2849 = "        p += k; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2849; }
    { const char * tb_v2850 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2850; }
    { const char * tb_v2851 = "    return n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2851; }
    { const char * tb_v2852 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2852; }
    { const char * tb_v2853 = "// память о последних текстах: адрес, байты, буквы и где мы стояли (буква li начинается с байта bi).\n"; *(const char * *)tb_grow(v_lines) = tb_v2853; }
    { const char * tb_v2854 = "// s[i] подряд в цикле — шаг вперёд от прошлого места, а не счёт с начала.\n"; *(const char * *)tb_grow(v_lines) = tb_v2854; }
    { const char * tb_v2855 = "typedef struct { const char *p; long long nb, nl, li, bi; } tb_u8slot;\n"; *(const char * *)tb_grow(v_lines) = tb_v2855; }
    { const char * tb_v2856 = "TB_API _Thread_local tb_u8slot tb_u8c[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v2856; }
    { const char * tb_v2857 = "TB_API _Thread_local int tb_u8c_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v2857; }
    { const char * tb_v2858 = "TB_INL void tb_u8c_clear(void) { for (int k = 0; k < 4; k++) tb_u8c[k].p = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2858; }
    { const char * tb_v2859 = "// nb < 0: длину в байтах посчитать (текст не меняется); nb >= 0: текст, в который дописывают\n"; *(const char * *)tb_grow(v_lines) = tb_v2859; }
    { const char * tb_v2860 = "TB_API tb_u8slot *tb_u8info(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2860; }
    { const char * tb_v2861 = "    for (int k = 0; k < 4; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2861; }
    { const char * tb_v2862 = "        tb_u8slot *c = &tb_u8c[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v2862; }
    { const char * tb_v2863 = "        if (c->p != s) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2863; }
    { const char * tb_v2864 = "        if (nb < 0 || nb == c->nb) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2864; }
    { const char * tb_v2865 = "        if (nb > c->nb) {   // дописали в конец: досчитать только новое\n"; *(const char * *)tb_grow(v_lines) = tb_v2865; }
    { const char * tb_v2866 = "            // последняя буква могла быть недописанной: пересчитать с её начала (не дальше 3 байт назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v2866; }
    { const char * tb_v2867 = "            long long from = c->nb, b = c->nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v2867; }
    { const char * tb_v2868 = "            while (b > 0 && c->nb - b < 3 && ((unsigned char)s[b - 1] & 0xC0) == 0x80) b--;\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "            if (b > 0 && (unsigned char)s[b - 1] >= 0xC0) from = b - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "            c->nl = c->nl - tb_u8count(s + from, c->nb - from) + tb_u8count(s + from, nb - from);\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "            c->nb = nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
    { const char * tb_v2872 = "            if (c->bi > from) { c->li = 0; c->bi = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2872; }
    { const char * tb_v2873 = "            return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2873; }
    { const char * tb_v2874 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2874; }
    { const char * tb_v2875 = "        break;\n"; *(const char * *)tb_grow(v_lines) = tb_v2875; }
    { const char * tb_v2876 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2876; }
    { const char * tb_v2877 = "    tb_u8slot *c = &tb_u8c[tb_u8c_next];\n"; *(const char * *)tb_grow(v_lines) = tb_v2877; }
    { const char * tb_v2878 = "    tb_u8c_next = (tb_u8c_next + 1) & 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v2878; }
    { const char * tb_v2879 = "    c->p = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2879; }
    { const char * tb_v2880 = "    c->nb = nb >= 0 ? nb : (long long)strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v2880; }
    { const char * tb_v2881 = "    c->nl = tb_u8count(s, c->nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v2881; }
    { const char * tb_v2882 = "    c->li = 0; c->bi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2882; }
    { const char * tb_v2883 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v2883; }
    { const char * tb_v2884 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2884; }
    { const char * tb_v2885 = "TB_API long long tb_ulen(const char *s) { return tb_u8info(s, -1)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2885; }
    { const char * tb_v2886 = "TB_API long long tb_ulen_n(const char *s, long long nb) { return nb < 0 ? tb_ulen(s) : tb_u8info(s, nb)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2886; }
    { const char * tb_v2887 = "// байт, с которого начинается буква i (i == букв — конец текста)\n"; *(const char * *)tb_grow(v_lines) = tb_v2887; }
    { const char * tb_v2888 = "TB_API long long tb_u8off(tb_u8slot *c, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2888; }
    { const char * tb_v2889 = "    if (c->nl == c->nb) return i;   // одна латиница: буква = байт\n"; *(const char * *)tb_grow(v_lines) = tb_v2889; }
    { const char * tb_v2890 = "    const unsigned char *s = (const unsigned char *)c->p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2890; }
    { const char * tb_v2891 = "    long long li = c->li, bi = c->bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v2891; }
    { const char * tb_v2892 = "    if (i < li && i < li - i) { li = 0; bi = 0; }   // ближе к началу, чем к прошлому месту\n"; *(const char * *)tb_grow(v_lines) = tb_v2892; }
    { const char * tb_v2893 = "    while (li < i) { long long k = tb_u8n(s + bi); if (bi + k > c->nb) k = 1; bi += k; li++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2893; }
    { const char * tb_v2894 = "    while (li > i) {   // назад: на начало предыдущей буквы\n"; *(const char * *)tb_grow(v_lines) = tb_v2894; }
    { const char * tb_v2895 = "        long long b = bi - 1, back = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2895; }
    { const char * tb_v2896 = "        while (b > 0 && (s[b] & 0xC0) == 0x80 && back < 3) { b--; back++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2896; }
    { const char * tb_v2897 = "        if (b + tb_u8n(s + b) != bi) b = bi - 1;   // не сложилось в букву — один байт\n"; *(const char * *)tb_grow(v_lines) = tb_v2897; }
    { const char * tb_v2898 = "        bi = b; li--;\n"; *(const char * *)tb_grow(v_lines) = tb_v2898; }
    { const char * tb_v2899 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2899; }
    { const char * tb_v2900 = "    c->li = li; c->bi = bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v2900; }
    { const char * tb_v2901 = "    return bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v2901; }
    { const char * tb_v2902 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2902; }
    { const char * tb_v2903 = "// буквы из двух байт (русские, греческие...): готовые строки, как tb_chars для латиницы\n"; *(const char * *)tb_grow(v_lines) = tb_v2903; }
    { const char * tb_v2904 = "TB_API char tb_chars2[2048 * 4];\n"; *(const char * *)tb_grow(v_lines) = tb_v2904; }
    { const char * tb_v2905 = "TB_API const char *tb_u8text(const char *p, long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2905; }
    { const char * tb_v2906 = "    if (n == 1) return tb_chr((unsigned char)p[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v2906; }
    { const char * tb_v2907 = "    if (n == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2907; }
    { const char * tb_v2908 = "        unsigned cp = (((unsigned char)p[0] & 0x1F) << 6) | ((unsigned char)p[1] & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v2908; }
    { const char * tb_v2909 = "        char *t = tb_chars2 + cp * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2909; }
    { const char * tb_v2910 = "        if (!t[0]) { t[1] = p[1]; t[2] = 0; __atomic_store_n(&t[0], p[0], __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2910; }
    { const char * tb_v2911 = "        return t;\n"; *(const char * *)tb_grow(v_lines) = tb_v2911; }
    { const char * tb_v2912 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2912; }
    { const char * tb_v2913 = "    char *r = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2913; }
    { const char * tb_v2914 = "    memcpy(r, p, n); r[n] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2914; }
    { const char * tb_v2915 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v2915; }
    { const char * tb_v2916 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2916; }
    { const char * tb_v2917 = "// s[i]: буква номер i; n — длина в байтах, если компилятор её знает (текст, в который дописывают), иначе -1\n"; *(const char * *)tb_grow(v_lines) = tb_v2917; }
    { const char * tb_v2918 = "TB_API const char *tb_char_at(const char *s, long long i, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2918; }
    { const char * tb_v2919 = "    tb_u8slot *c = tb_u8info(s, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2919; }
    { const char * tb_v2920 = "    if (i < 0 || i >= c->nl) tb_crash(line, \"номер за пределами текста\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2920; }
    { const char * tb_v2921 = "    if (c->nl == c->nb) return tb_chr((unsigned char)s[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v2921; }
    { const char * tb_v2922 = "    long long b = tb_u8off(c, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v2922; }
