    { const char * tb_v2926 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2926; }
    { const char * tb_v2927 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2927; }
    { const char * tb_v2928 = "TB_API const char *tb_u8take(const char *s, long long *i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2928; }
    { const char * tb_v2929 = "    const unsigned char *p = (const unsigned char *)s + *i;\n"; *(const char * *)tb_grow(v_lines) = tb_v2929; }
    { const char * tb_v2930 = "    if (*p < 0x80) return tb_chr(*p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2930; }
