    { const char * tb_v2934 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2934; }
    { const char * tb_v2935 = "// s += b: дописать в конец своей памяти s, а не собирать третий текст из двух.\n"; *(const char * *)tb_grow(v_lines) = tb_v2935; }
    { const char * tb_v2936 = "// *rl — длина s в своей памяти (-1: своей памяти нет, s могли сохранить где-то ещё — сначала копия),\n"; *(const char * *)tb_grow(v_lines) = tb_v2936; }
