    { const char * tb_v2968 = "        long long la = (long long)strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v2968; }
    { const char * tb_v2969 = "        long long cap = 2 * (la + lb) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2969; }
    { const char * tb_v2970 = "        if (cap < 64) cap = 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v2970; }
    { const char * tb_v2971 = "        char *r = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v2971; }
