    { const char * tb_v2975 = "        *p = r; *rl = la + lb; *rc = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2975; }
    { const char * tb_v2976 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2976; }
    { const char * tb_v2977 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2977; }
    { const char * tb_v2978 = "    long long need = *rl + lb + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2978; }
    { const char * tb_v2979 = "    if (need > *rc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2979; }
    { const char * tb_v2980 = "        long long cap = 2 * need;\n"; *(const char * *)tb_grow(v_lines) = tb_v2980; }
    { const char * tb_v2981 = "        long long off = (b >= s && b < s + *rc) ? b - s : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2981; }
    { const char * tb_v2982 = "        s = tb_resize(s, *rl + 1, cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v2982; }
    { const char * tb_v2983 = "        if (off >= 0) b = s + off;\n"; *(const char * *)tb_grow(v_lines) = tb_v2983; }
    { const char * tb_v2984 = "        *p = s; *rc = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2984; }
    { const char * tb_v2985 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2985; }
    { const char * tb_v2986 = "    memmove(s + *rl, b, lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v2986; }
    { const char * tb_v2987 = "    *rl += lb;\n"; *(const char * *)tb_grow(v_lines) = tb_v2987; }
    { const char * tb_v2988 = "    s[*rl] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2988; }
    { const char * tb_v2989 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2989; }
