    { const char * tb_v3017 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3017; }
    { const char * tb_v3018 = "// char(1087) → \"п\": буква по её номеру в Юникоде\n"; *(const char * *)tb_grow(v_lines) = tb_v3018; }
    { const char * tb_v3019 = "TB_API const char *tb_uchr(long long x, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3019; }
    { const char * tb_v3020 = "    if (x < 1 || x > 0x10FFFF || (x >= 0xD800 && x <= 0xDFFF)) tb_crash(line, \"char: такого номера буквы нет (от 1 до 1114111)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3020; }
