    { const char * tb_v3266 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3266; }
    { const char * tb_v3267 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3267; }
