    { const char * tb_v4170 = "            if (g[i] != 0xFB) tb_mem_die(line, \"кто-то писал за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4170; }
    { const char * tb_v4171 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4171; }
