    { const char * tb_v4206 = "        memcpy((void *)(uintptr_t)b, (void *)(uintptr_t)a, (size_t)(old < (uint64_t)n ? old : (uint64_t)n));\n"; *(const char * *)tb_grow(v_lines) = tb_v4206; }
    { const char * tb_v4207 = "        tb_mem_bury(a, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4207; }
