    { const char * tb_v5359 = "// GIF: первый кадр (LZW), палитра общая или своя, прозрачный цвет, через строку (interlace)\n"; *(const char * *)tb_grow(v_lines) = tb_v5359; }
    { const char * tb_v5360 = "TB_API uint32_t *tb_gif(const unsigned char *d, size_t n, int *pw, int *ph, const char **why) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5360; }
    { const char * tb_v5361 = "    *why = \"это не GIF\";\n"; *(const char * *)tb_grow(v_lines) = tb_v5361; }
    { const char * tb_v5362 = "    if (n < 13 || memcmp(d, \"GIF8\", 4) != 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5362; }
    { const char * tb_v5363 = "    int w = d[6] | d[7] << 8, h = d[8] | d[9] << 8, fl = d[10];\n"; *(const char * *)tb_grow(v_lines) = tb_v5363; }
