    { const char * tb_v5535 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5535; }
    { const char * tb_v5536 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5536; }
    { const char * tb_v5537 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5537; }
    { const char * tb_v5538 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v5538; }
    { const char * tb_v5539 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v5539; }
    { const char * tb_v5540 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5540; }
    { const char * tb_v5541 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5541; }
    { const char * tb_v5542 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5542; }
    { const char * tb_v5543 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5543; }
    { const char * tb_v5544 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5544; }
    { const char * tb_v5545 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5545; }
    { const char * tb_v5546 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5546; }
    { const char * tb_v5547 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5547; }
    { const char * tb_v5548 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5548; }
    { const char * tb_v5549 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5549; }
    { const char * tb_v5550 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v5550; }
    { const char * tb_v5551 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5551; }
    { const char * tb_v5552 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5552; }
    { const char * tb_v5553 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5553; }
    { const char * tb_v5554 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v5554; }
    { const char * tb_v5555 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5555; }
    { const char * tb_v5556 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5556; }
    { const char * tb_v5557 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5557; }
    { const char * tb_v5558 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v5558; }
    { const char * tb_v5559 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5559; }
    { const char * tb_v5560 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5560; }
    { const char * tb_v5561 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v5561; }
    { const char * tb_v5562 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v5562; }
    { const char * tb_v5563 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5563; }
    { const char * tb_v5564 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v5564; }
    { const char * tb_v5565 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5565; }
    { const char * tb_v5566 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5566; }
    { const char * tb_v5567 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5567; }
    { const char * tb_v5568 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5568; }
    { const char * tb_v5569 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5569; }
    { const char * tb_v5570 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5570; }
    { const char * tb_v5571 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v5571; }
    { const char * tb_v5572 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5572; }
    { const char * tb_v5573 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v5573; }
    { const char * tb_v5574 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5574; }
    { const char * tb_v5575 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v5575; }
    { const char * tb_v5576 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5576; }
    { const char * tb_v5577 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5577; }
    { const char * tb_v5578 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5578; }
    { const char * tb_v5579 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5579; }
    { const char * tb_v5580 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5580; }
    { const char * tb_v5581 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5581; }
    { const char * tb_v5582 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v5582; }
    { const char * tb_v5583 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5583; }
    { const char * tb_v5584 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v5584; }
    { const char * tb_v5585 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5585; }
    { const char * tb_v5586 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5586; }
    { const char * tb_v5587 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5587; }
    { const char * tb_v5588 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5588; }
    { const char * tb_v5589 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v5589; }
    { const char * tb_v5590 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5590; }
    { const char * tb_v5591 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5591; }
    { const char * tb_v5592 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v5592; }
    { const char * tb_v5593 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v5593; }
    { const char * tb_v5594 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5594; }
    { const char * tb_v5595 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5595; }
    { const char * tb_v5596 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5596; }
    { const char * tb_v5597 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5597; }
    { const char * tb_v5598 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5598; }
    { const char * tb_v5599 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v5599; }
    { const char * tb_v5600 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5600; }
    { const char * tb_v5601 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v5601; }
    { const char * tb_v5602 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5602; }
    { const char * tb_v5603 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v5603; }
    { const char * tb_v5604 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5604; }
    { const char * tb_v5605 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5605; }
    { const char * tb_v5606 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5606; }
    { const char * tb_v5607 = "    if (u > 0xFFFF) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5607; }
    { const char * tb_v5608 = "    unsigned segs = tb_u16(f, c + 6) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5608; }
    { const char * tb_v5609 = "    size_t ends = c + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, ranges = deltas + 2 * segs;\n"; *(const char * *)tb_grow(v_lines) = tb_v5609; }
    { const char * tb_v5610 = "    for (unsigned i = 0; i < segs; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5610; }
    { const char * tb_v5611 = "        if (u > tb_u16(f, ends + 2 * i)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5611; }
    { const char * tb_v5612 = "        unsigned s = tb_u16(f, starts + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5612; }
    { const char * tb_v5613 = "        if (u < s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5613; }
    { const char * tb_v5614 = "        unsigned delta = tb_u16(f, deltas + 2 * i), ro = tb_u16(f, ranges + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5614; }
    { const char * tb_v5615 = "        if (ro == 0) return (u + delta) & 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v5615; }
    { const char * tb_v5616 = "        unsigned g = tb_u16(f, ranges + 2 * i + ro + 2 * (u - s));\n"; *(const char * *)tb_grow(v_lines) = tb_v5616; }
    { const char * tb_v5617 = "        return g ? (g + delta) & 0xFFFF : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5617; }
    { const char * tb_v5618 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5618; }
    { const char * tb_v5619 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5619; }
    { const char * tb_v5620 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5620; }
    { const char * tb_v5621 = "static double tb_ttf_adv(const tb_font_t *f, unsigned g) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5621; }
    { const char * tb_v5622 = "    unsigned i = (int)g < f->nhm ? g : (unsigned)f->nhm - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5622; }
    { const char * tb_v5623 = "    return tb_u16(f, f->hmtx + 4 * (size_t)i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5623; }
    { const char * tb_v5624 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5624; }
    { const char * tb_v5625 = "static size_t tb_ttf_gpos(const tb_font_t *f, unsigned g, size_t *len) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5625; }
    { const char * tb_v5626 = "    if ((int)g >= f->nglyphs) { *len = 0; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5626; }
    { const char * tb_v5627 = "    size_t a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v5627; }
    { const char * tb_v5628 = "    if (f->locfmt == 0) { a = 2 * (size_t)tb_u16(f, f->loca + 2 * g); b = 2 * (size_t)tb_u16(f, f->loca + 2 * g + 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5628; }
    { const char * tb_v5629 = "    else { a = tb_u32(f, f->loca + 4 * g); b = tb_u32(f, f->loca + 4 * g + 4); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5629; }
    { const char * tb_v5630 = "    *len = b > a ? b - a : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5630; }
    { const char * tb_v5631 = "    return f->glyf + a;\n"; *(const char * *)tb_grow(v_lines) = tb_v5631; }
    { const char * tb_v5632 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5632; }
    { const char * tb_v5633 = "// контур буквы → отрезки (в точках экрана, y вниз); m — матрица шрифт → экран: x' = m0 x + m2 y + m4, y' = m1 x + m3 y + m5\n"; *(const char * *)tb_grow(v_lines) = tb_v5633; }
    { const char * tb_v5634 = "typedef struct { float *e; int n, cap; } tb_edges;\n"; *(const char * *)tb_grow(v_lines) = tb_v5634; }
    { const char * tb_v5635 = "static void tb_edge(tb_edges *E, double x0, double y0, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5635; }
    { const char * tb_v5636 = "    if (y0 == y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5636; }
    { const char * tb_v5637 = "    if (E->n == E->cap) { E->cap = E->cap ? E->cap * 2 : 256; E->e = realloc(E->e, (size_t)E->cap * 4 * sizeof(float)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5637; }
    { const char * tb_v5638 = "    float *p = E->e + 4 * E->n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5638; }
    { const char * tb_v5639 = "    p[0] = (float)x0; p[1] = (float)y0; p[2] = (float)x1; p[3] = (float)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5639; }
    { const char * tb_v5640 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5640; }
    { const char * tb_v5641 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5641; }
    { const char * tb_v5642 = "    double dx = x0 - 2 * cx + x1, dy = y0 - 2 * cy + y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5642; }
    { const char * tb_v5643 = "    int n = 1 + (int)sqrt(sqrt(dx * dx + dy * dy) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5643; }
    { const char * tb_v5644 = "    if (n > 16) n = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v5644; }
    { const char * tb_v5645 = "    double px = x0, py = y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5645; }
    { const char * tb_v5646 = "    for (int i = 1; i <= n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5646; }
    { const char * tb_v5647 = "        double t = (double)i / n, u = 1 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5647; }
    { const char * tb_v5648 = "        double qx = u * u * x0 + 2 * u * t * cx + t * t * x1, qy = u * u * y0 + 2 * u * t * cy + t * t * y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5648; }
    { const char * tb_v5649 = "        tb_edge(E, px, py, qx, qy);\n"; *(const char * *)tb_grow(v_lines) = tb_v5649; }
    { const char * tb_v5650 = "        px = qx; py = qy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5650; }
    { const char * tb_v5651 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5651; }
    { const char * tb_v5652 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5652; }
    { const char * tb_v5653 = "static void tb_ttf_outline(const tb_font_t *f, unsigned g, const double *m, tb_edges *E, int depth) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5653; }
    { const char * tb_v5654 = "    size_t len, o = tb_ttf_gpos(f, g, &len);\n"; *(const char * *)tb_grow(v_lines) = tb_v5654; }
    { const char * tb_v5655 = "    if (len < 10 || depth > 8) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5655; }
    { const char * tb_v5656 = "    int nc = tb_s16(f, o);\n"; *(const char * *)tb_grow(v_lines) = tb_v5656; }
    { const char * tb_v5657 = "    if (nc < 0) {   // составная буква (ё = е + точки): части со своим сдвигом и масштабом\n"; *(const char * *)tb_grow(v_lines) = tb_v5657; }
