    { const char * tb_v5856 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v5856; }
    { const char * tb_v5857 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5857; }
    { const char * tb_v5858 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5858; }
    { const char * tb_v5859 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v5859; }
    { const char * tb_v5860 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5860; }
    { const char * tb_v5861 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5861; }
    { const char * tb_v5862 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5862; }
    { const char * tb_v5863 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5863; }
    { const char * tb_v5864 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5864; }
    { const char * tb_v5865 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5865; }
    { const char * tb_v5866 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5866; }
    { const char * tb_v5867 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5867; }
    { const char * tb_v5868 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5868; }
    { const char * tb_v5869 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5869; }
    { const char * tb_v5870 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5870; }
    { const char * tb_v5871 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v5871; }
