    { const char * tb_v5873 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5873; }
    { const char * tb_v5874 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v5874; }
    { const char * tb_v5875 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5875; }
    { const char * tb_v5876 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5876; }
    { const char * tb_v5877 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5877; }
    { const char * tb_v5878 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5878; }
