    { const char * tb_v5892 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5892; }
    { const char * tb_v5893 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v5893; }
    { const char * tb_v5894 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v5894; }
    { const char * tb_v5895 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v5895; }
    { const char * tb_v5896 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v5896; }
    { const char * tb_v5897 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v5897; }
    { const char * tb_v5898 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5898; }
    { const char * tb_v5899 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v5899; }
    { const char * tb_v5900 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5900; }
    { const char * tb_v5901 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5901; }
    { const char * tb_v5902 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5902; }
