    { const char * tb_v5955 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5955; }
    { const char * tb_v5956 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v5956; }
    { const char * tb_v5957 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5957; }
    { const char * tb_v5958 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5958; }
    { const char * tb_v5959 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5959; }
    { const char * tb_v5960 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v5960; }
    { const char * tb_v5961 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5961; }
    { const char * tb_v5962 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v5962; }
    { const char * tb_v5963 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5963; }
    { const char * tb_v5964 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5964; }
    { const char * tb_v5965 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5965; }
    { const char * tb_v5966 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v5966; }
    { const char * tb_v5967 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5967; }
    { const char * tb_v5968 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5968; }
    { const char * tb_v5969 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v5969; }
    { const char * tb_v5970 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5970; }
    { const char * tb_v5971 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v5971; }
    { const char * tb_v5972 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v5972; }
    { const char * tb_v5973 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5973; }
    { const char * tb_v5974 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5974; }
    { const char * tb_v5975 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v5975; }
    { const char * tb_v5976 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5976; }
    { const char * tb_v5977 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5977; }
    { const char * tb_v5978 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5978; }
    { const char * tb_v5979 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5979; }
    { const char * tb_v5980 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5980; }
    { const char * tb_v5981 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5981; }
    { const char * tb_v5982 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5982; }
    { const char * tb_v5983 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5983; }
    { const char * tb_v5984 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v5984; }
    { const char * tb_v5985 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v5985; }
    { const char * tb_v5986 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5986; }
    { const char * tb_v5987 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5987; }
    { const char * tb_v5988 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5988; }
    { const char * tb_v5989 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5989; }
    { const char * tb_v5990 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5990; }
    { const char * tb_v5991 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v5991; }
    { const char * tb_v5992 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5992; }
    { const char * tb_v5993 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v5993; }
    { const char * tb_v5994 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5994; }
    { const char * tb_v5995 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v5995; }
    { const char * tb_v5996 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5996; }
    { const char * tb_v5997 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5997; }
    { const char * tb_v5998 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5998; }
    { const char * tb_v5999 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v5999; }
    { const char * tb_v6000 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6000; }
    { const char * tb_v6001 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6001; }
    { const char * tb_v6002 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6002; }
    { const char * tb_v6003 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6003; }
    { const char * tb_v6004 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6004; }
    { const char * tb_v6005 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6005; }
    { const char * tb_v6006 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6006; }
    { const char * tb_v6007 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6007; }
    { const char * tb_v6008 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6008; }
    { const char * tb_v6009 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6009; }
    { const char * tb_v6010 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6010; }
    { const char * tb_v6011 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6011; }
    { const char * tb_v6012 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6012; }
    { const char * tb_v6013 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6013; }
    { const char * tb_v6014 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6014; }
    { const char * tb_v6015 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6015; }
    { const char * tb_v6016 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6016; }
    { const char * tb_v6017 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6017; }
    { const char * tb_v6018 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6018; }
    { const char * tb_v6019 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6019; }
    { const char * tb_v6020 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v6020; }
    { const char * tb_v6021 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6021; }
    { const char * tb_v6022 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6022; }
    { const char * tb_v6023 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v6023; }
    { const char * tb_v6024 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6024; }
    { const char * tb_v6025 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6025; }
    { const char * tb_v6026 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v6026; }
    { const char * tb_v6027 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v6027; }
    { const char * tb_v6028 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6028; }
    { const char * tb_v6029 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6029; }
    { const char * tb_v6030 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6030; }
    { const char * tb_v6031 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6031; }
    { const char * tb_v6032 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6032; }
    { const char * tb_v6033 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6033; }
    { const char * tb_v6034 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6034; }
    { const char * tb_v6035 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6035; }
    { const char * tb_v6036 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6036; }
    { const char * tb_v6037 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v6037; }
    { const char * tb_v6038 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6038; }
    { const char * tb_v6039 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v6039; }
    { const char * tb_v6040 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6040; }
    { const char * tb_v6041 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6041; }
    { const char * tb_v6042 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6042; }
    { const char * tb_v6043 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6043; }
    { const char * tb_v6044 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6044; }
    { const char * tb_v6045 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (1u << 29) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v6045; }
    { const char * tb_v6046 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6046; }
    { const char * tb_v6047 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v6047; }
    { const char * tb_v6048 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v6048; }
    { const char * tb_v6049 = "TB_API void tb_gpu_triangle(const long long *t, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6049; }
    { const char * tb_v6050 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 1u);\n"; *(const char * *)tb_grow(v_lines) = tb_v6050; }
    { const char * tb_v6051 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6051; }
    { const char * tb_v6052 = "// треугольник сетки (3D): как треугольник, плюс плоскость глубины в tb_gplane\n"; *(const char * *)tb_grow(v_lines) = tb_v6052; }
    { const char * tb_v6053 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6053; }
    { const char * tb_v6054 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6054; }
    { const char * tb_v6055 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin);\n"; *(const char * *)tb_grow(v_lines) = tb_v6055; }
    { const char * tb_v6056 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v6056; }
    { const char * tb_v6057 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6057; }
    { const char * tb_v6058 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v6058; }
    { const char * tb_v6059 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6059; }
    { const char * tb_v6060 = "// треугольник сетки с картинкой: плоскость глубины и запись текстуры; m = 2 | бит 29 | (место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v6060; }
    { const char * tb_v6061 = "// какой конвейер у фигуры: 0 — 2D, 1 — 3D (глубина), 2 — 3D с картинкой\n"; *(const char * *)tb_grow(v_lines) = tb_v6061; }
    { const char * tb_v6062 = "// 3 — «новый» треугольник, 4 — он же прозрачный (глубину не пишет)\n"; *(const char * *)tb_grow(v_lines) = tb_v6062; }
    { const char * tb_v6063 = "TB_INL int tb_gkind(uint32_t m) { return (m & 0xC0000003u) != 2u ? 0 : (m >> 28) & 1u ? 3 + (int)((m >> 27) & 1u) : (m >> 29) & 1u ? 2 : 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6063; }
    { const char * tb_v6064 = "TB_API void tb_gpu_tri3t(const long long *t, long long c, const uint32_t *pl, const tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6064; }
    { const char * tb_v6065 = "    if (tb_gin == TB_GI_CAP || tb_gtn == TB_GT_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6065; }
    { const char * tb_v6066 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin), gt = (uint32_t)(tb_gslot * TB_GT_CAP + tb_gtn++);\n"; *(const char * *)tb_grow(v_lines) = tb_v6066; }
    { const char * tb_v6067 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v6067; }
    { const char * tb_v6068 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = gt;\n"; *(const char * *)tb_grow(v_lines) = tb_v6068; }
    { const char * tb_v6069 = "    tb_gtex[gt] = *tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v6069; }
    { const char * tb_v6070 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (1u << 29) | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v6070; }
    { const char * tb_v6071 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6071; }
    { const char * tb_v6072 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6072; }
    { const char * tb_v6073 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6073; }
    { const char * tb_v6074 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6074; }
    { const char * tb_v6075 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6075; }
    { const char * tb_v6076 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6076; }
    { const char * tb_v6077 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6077; }
    { const char * tb_v6078 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6078; }
    { const char * tb_v6079 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6079; }
    { const char * tb_v6080 = "    long long x1 = x + 8 * size > tb_gw ? tb_gw : x + 8 * size, y1 = y + 16 * size > tb_gh ? tb_gh : y + 16 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6080; }
    { const char * tb_v6081 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6081; }
    { const char * tb_v6082 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6082; }
    { const char * tb_v6083 = "#if !defined(__APPLE__) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v6083; }
    { const char * tb_v6084 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v6084; }
