    { const char * tb_v8827 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v8827; }
    { const char * tb_v8828 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8828; }
    { const char * tb_v8829 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8829; }
