    { const char * tb_v8851 = "        tb_my = (int)((uint64_t)r[2] * (uint64_t)tb_gh / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v8851; }
    { const char * tb_v8852 = "        int down = (r[0] & 0x20) != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8852; }
    { const char * tb_v8853 = "        if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8853; }
