    { const char * tb_v8858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8858; }
    { const char * tb_v8859 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8859; }
    { const char * tb_v8860 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v8860; }
