    { const char * tb_v8864 = "    if (tb_vmm) { tb_vmm_read(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8864; }
    { const char * tb_v8865 = "    if (tb_mpn == 0 && !(b & 8)) return;           // первый байт пакета всегда с битом 3\n"; *(const char * *)tb_grow(v_lines) = tb_v8865; }
    { const char * tb_v8866 = "    tb_mpk[tb_mpn++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v8866; }
