    { const char * tb_v8875 = "    if (tb_my >= tb_gh) tb_my = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8875; }
    { const char * tb_v8876 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8876; }
    { const char * tb_v8877 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8877; }
