    { const char * tb_v10105 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v10105; }
    { const char * tb_v10106 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10106; }
    { const char * tb_v10107 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10107; }
    { const char * tb_v10108 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10108; }
    { const char * tb_v10109 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10109; }
