    { const char * tb_v10112 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10112; }
    { const char * tb_v10113 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10113; }
    { const char * tb_v10114 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10114; }
    { const char * tb_v10115 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v10115; }
    { const char * tb_v10116 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v10116; }
    { const char * tb_v10117 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v10117; }
    { const char * tb_v10118 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10118; }
    { const char * tb_v10119 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10119; }
    { const char * tb_v10120 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10120; }
    { const char * tb_v10121 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10121; }
    { const char * tb_v10122 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10122; }
    { const char * tb_v10123 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10123; }
    { const char * tb_v10124 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v10124; }
    { const char * tb_v10125 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10125; }
