    { const char * tb_v10148 = "    tb_px = np; tb_gw = nw; tb_gh = nh;\n"; *(const char * *)tb_grow(v_lines) = tb_v10148; }
    { const char * tb_v10149 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v10149; }
    { const char * tb_v10150 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10150; }
    { const char * tb_v10151 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10151; }
    { const char * tb_v10152 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10152; }
