    { const char * tb_v10154 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v10154; }
    { const char * tb_v10155 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10155; }
    { const char * tb_v10156 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10156; }
    { const char * tb_v10157 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10157; }
    { const char * tb_v10158 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10158; }
    { const char * tb_v10159 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10159; }
    { const char * tb_v10160 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10160; }
    { const char * tb_v10161 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10161; }
    { const char * tb_v10162 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10162; }
    { const char * tb_v10163 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10163; }
    { const char * tb_v10164 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10164; }
    { const char * tb_v10165 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v10165; }
    { const char * tb_v10166 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10166; }
    { const char * tb_v10167 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10167; }
    { const char * tb_v10168 = "    TB_SCENE();        // сцена 3D, которая ждала (тени, прозрачные) — в этот кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v10168; }
    { const char * tb_v10169 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v10169; }
    { const char * tb_v10170 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v10170; }
    { const char * tb_v10171 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v10171; }
    { const char * tb_v10172 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v10172; }
    { const char * tb_v10173 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10173; }
    { const char * tb_v10174 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10174; }
    { const char * tb_v10175 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10175; }
    { const char * tb_v10176 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v10176; }
    { const char * tb_v10177 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10177; }
    { const char * tb_v10178 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v10178; }
    { const char * tb_v10179 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v10179; }
    { const char * tb_v10180 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v10180; }
    { const char * tb_v10181 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v10181; }
    { const char * tb_v10182 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10182; }
    { const char * tb_v10183 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10183; }
    { const char * tb_v10184 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v10184; }
    { const char * tb_v10185 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v10185; }
    { const char * tb_v10186 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v10186; }
    { const char * tb_v10187 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10187; }
    { const char * tb_v10188 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v10188; }
    { const char * tb_v10189 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v10189; }
    { const char * tb_v10190 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10190; }
