    { const char * tb_v10238 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10238; }
    { const char * tb_v10239 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v10239; }
    { const char * tb_v10240 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v10240; }
    { const char * tb_v10241 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10241; }
    { const char * tb_v10242 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10242; }
