    { const char * tb_v10260 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10260; }
    { const char * tb_v10261 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v10261; }
