    { const char * tb_v10271 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v10271; }
    { const char * tb_v10272 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10272; }
    { const char * tb_v10273 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v10273; }
    { const char * tb_v10274 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10274; }
    { const char * tb_v10275 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v10275; }
    { const char * tb_v10276 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10276; }
