    { const char * tb_v10282 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10282; }
    { const char * tb_v10283 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v10283; }
    { const char * tb_v10284 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10284; }
    { const char * tb_v10285 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v10285; }
