    { const char * tb_v10288 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10288; }
    { const char * tb_v10289 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10289; }
    { const char * tb_v10290 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10290; }
