    { const char * tb_v10302 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v10302; }
    { const char * tb_v10303 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10303; }
    { const char * tb_v10304 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v10304; }
    { const char * tb_v10305 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v10305; }
    { const char * tb_v10306 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v10306; }
    { const char * tb_v10307 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v10307; }
