    { const char * tb_v10340 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v10340; }
