    { const char * tb_v10356 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v10356; }
    { const char * tb_v10357 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10357; }
