    { const char * tb_v10375 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v10375; }
    { const char * tb_v10376 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10376; }
    { const char * tb_v10377 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10377; }
    { const char * tb_v10378 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v10378; }
    { const char * tb_v10379 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10379; }
    { const char * tb_v10380 = "                long long fx = xx * 128 - 64; if (fx < 0) fx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10380; }
    { const char * tb_v10381 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v10381; }
    { const char * tb_v10382 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10382; }
    { const char * tb_v10383 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10383; }
    { const char * tb_v10384 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v10384; }
    { const char * tb_v10385 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v10385; }
    { const char * tb_v10386 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v10386; }
    { const char * tb_v10387 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v10387; }
    { const char * tb_v10388 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10388; }
    { const char * tb_v10389 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10389; }
    { const char * tb_v10390 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v10390; }
    { const char * tb_v10391 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v10391; }
    { const char * tb_v10392 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v10392; }
    { const char * tb_v10393 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10393; }
    { const char * tb_v10394 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10394; }
    { const char * tb_v10395 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10395; }
    { const char * tb_v10396 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10396; }
    { const char * tb_v10397 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v10397; }
    { const char * tb_v10398 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v10398; }
    { const char * tb_v10399 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v10399; }
    { const char * tb_v10400 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v10400; }
    { const char * tb_v10401 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v10401; }
