    { const char * tb_v10407 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10407; }
    { const char * tb_v10408 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10408; }
    { const char * tb_v10409 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10409; }
    { const char * tb_v10410 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10410; }
    { const char * tb_v10411 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10411; }
    { const char * tb_v10412 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v10412; }
    { const char * tb_v10413 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v10413; }
