    { const char * tb_v10418 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v10418; }
    { const char * tb_v10419 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10419; }
