    { const char * tb_v10422 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10422; }
    { const char * tb_v10423 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v10423; }
    { const char * tb_v10424 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10424; }
    { const char * tb_v10425 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v10425; }
    { const char * tb_v10426 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v10426; }
    { const char * tb_v10427 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v10427; }
    { const char * tb_v10428 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v10428; }
    { const char * tb_v10429 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v10429; }
    { const char * tb_v10430 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10430; }
    { const char * tb_v10431 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v10431; }
    { const char * tb_v10432 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10432; }
    { const char * tb_v10433 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10433; }
    { const char * tb_v10434 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10434; }
    { const char * tb_v10435 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10435; }
    { const char * tb_v10436 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10436; }
    { const char * tb_v10437 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v10437; }
    { const char * tb_v10438 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10438; }
    { const char * tb_v10439 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10439; }
    { const char * tb_v10440 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10440; }
    { const char * tb_v10441 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v10441; }
    { const char * tb_v10442 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v10442; }
    { const char * tb_v10443 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10443; }
    { const char * tb_v10444 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v10444; }
    { const char * tb_v10445 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10445; }
    { const char * tb_v10446 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10446; }
    { const char * tb_v10447 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v10447; }
    { const char * tb_v10448 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v10448; }
    { const char * tb_v10449 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10449; }
    { const char * tb_v10450 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v10450; }
    { const char * tb_v10451 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v10451; }
    { const char * tb_v10452 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10452; }
    { const char * tb_v10453 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10453; }
    { const char * tb_v10454 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v10454; }
    { const char * tb_v10455 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v10455; }
    { const char * tb_v10456 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10456; }
    { const char * tb_v10457 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v10457; }
