    { const char * tb_v10529 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10529; }
    { const char * tb_v10530 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v10530; }
    { const char * tb_v10531 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10531; }
