    { const char * tb_v10588 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v10588; }
    { const char * tb_v10589 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v10589; }
    { const char * tb_v10590 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10590; }
    { const char * tb_v10591 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v10591; }
    { const char * tb_v10592 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v10592; }
    { const char * tb_v10593 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10593; }
    { const char * tb_v10594 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10594; }
    { const char * tb_v10595 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10595; }
    { const char * tb_v10596 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10596; }
    { const char * tb_v10597 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10597; }
    { const char * tb_v10598 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10598; }
    { const char * tb_v10599 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v10599; }
    { const char * tb_v10600 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10600; }
    { const char * tb_v10601 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v10601; }
    { const char * tb_v10602 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10602; }
    { const char * tb_v10603 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10603; }
    { const char * tb_v10604 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10604; }
    { const char * tb_v10605 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v10605; }
    { const char * tb_v10606 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10606; }
    { const char * tb_v10607 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10607; }
    { const char * tb_v10608 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10608; }
    { const char * tb_v10609 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10609; }
    { const char * tb_v10610 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v10610; }
    { const char * tb_v10611 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v10611; }
    { const char * tb_v10612 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10612; }
    { const char * tb_v10613 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v10613; }
    { const char * tb_v10614 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v10614; }
    { const char * tb_v10615 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10615; }
    { const char * tb_v10616 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v10616; }
    { const char * tb_v10617 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v10617; }
    { const char * tb_v10618 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10618; }
    { const char * tb_v10619 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v10619; }
    { const char * tb_v10620 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v10620; }
    { const char * tb_v10621 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v10621; }
    { const char * tb_v10622 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10622; }
    { const char * tb_v10623 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10623; }
    { const char * tb_v10624 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v10624; }
    { const char * tb_v10625 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v10625; }
    { const char * tb_v10626 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v10626; }
    { const char * tb_v10627 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v10627; }
    { const char * tb_v10628 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v10628; }
    { const char * tb_v10629 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v10629; }
    { const char * tb_v10630 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v10630; }
    { const char * tb_v10631 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10631; }
    { const char * tb_v10632 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v10632; }
    { const char * tb_v10633 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v10633; }
    { const char * tb_v10634 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v10634; }
    { const char * tb_v10635 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10635; }
    { const char * tb_v10636 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v10636; }
    { const char * tb_v10637 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10637; }
    { const char * tb_v10638 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10638; }
    { const char * tb_v10639 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v10639; }
    { const char * tb_v10640 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v10640; }
    { const char * tb_v10641 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v10641; }
    { const char * tb_v10642 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v10642; }
    { const char * tb_v10643 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v10643; }
    { const char * tb_v10644 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v10644; }
    { const char * tb_v10645 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v10645; }
    { const char * tb_v10646 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v10646; }
    { const char * tb_v10647 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v10647; }
    { const char * tb_v10648 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v10648; }
    { const char * tb_v10649 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v10649; }
    { const char * tb_v10650 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v10650; }
    { const char * tb_v10651 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v10651; }
    { const char * tb_v10652 = "typedef struct { int parent; double piv[3], rot[3], mv[3]; } tb_bone_t;   // кость: родитель, сустав, поворот, сдвиг\n"; *(const char * *)tb_grow(v_lines) = tb_v10652; }
    { const char * tb_v10653 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v10653; }
    { const char * tb_v10654 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v10654; }
    { const char * tb_v10655 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v10655; }
    { const char * tb_v10656 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v10656; }
    { const char * tb_v10657 = "    long long nch, *chr; double *chs, bs[4]; int chok;\n"; *(const char * *)tb_grow(v_lines) = tb_v10657; }
