    { const char * tb_v10659 = "    tb_bone_t *bones; long long nb, capb; int16_t *sb; float *sw; } tb_mesh;     // кости и у каждого угла до 4 костей с весами   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v10659; }
    { const char * tb_v10660 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10660; }
    { const char * tb_v10661 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10661; }
    { const char * tb_v10662 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v10662; }
    { const char * tb_v10663 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v10663; }
    { const char * tb_v10664 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10664; }
    { const char * tb_v10665 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10665; }
