    { const char * tb_v10690 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10690; }
    { const char * tb_v10691 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v10691; }
