    { const char * tb_v10705 = "            m->sb = (int16_t *)realloc(m->sb, sizeof(int16_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v10705; }
    { const char * tb_v10706 = "            m->sw = (float *)realloc(m->sw, sizeof(float) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v10706; }
    { const char * tb_v10707 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10707; }
    { const char * tb_v10708 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10708; }
    { const char * tb_v10709 = "    if (m->sb) for (int i = 0; i < 4; i++) { m->sb[4 * m->nv + i] = -1; m->sw[4 * m->nv + i] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10709; }
    { const char * tb_v10710 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10710; }
