    { const char * tb_v10780 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10780; }
    { const char * tb_v10781 = "// ---- свет: одно солнце (направление к нему) и фон; яркость грани — от того, как она повёрнута к солнцу ----\n"; *(const char * *)tb_grow(v_lines) = tb_v10781; }
    { const char * tb_v10782 = "// Всё в целых, одной формулой на процессоре и на видеокарте (tb3.vert, tb3.metal): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v10782; }
