    { const char * tb_v10784 = "TB_API int tb_lamb = -1;   // фон × 256; -1 — света нет, цвета как есть\n"; *(const char * *)tb_grow(v_lines) = tb_v10784; }
    { const char * tb_v10785 = "TB_API double tb_amb0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10785; }
    { const char * tb_v10786 = "TB_API void tb_light(double dx, double dy, double dz, double amb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10786; }
    { const char * tb_v10787 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10787; }
    { const char * tb_v10788 = "    double l = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v10788; }
