    { const char * tb_v10796 = "// нормали треугольников: (b - a) × (c - a), длина 2^14. У куба, где грани по кругу против часовой\n"; *(const char * *)tb_grow(v_lines) = tb_v10796; }
    { const char * tb_v10797 = "// стрелки снаружи, нормаль смотрит наружу\n"; *(const char * *)tb_grow(v_lines) = tb_v10797; }
    { const char * tb_v10798 = "static void tb_mesh_normals(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10798; }
    { const char * tb_v10799 = "    if (m->nrmok) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10799; }
    { const char * tb_v10800 = "    m->nrmok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10800; }
    { const char * tb_v10801 = "    if (m->nrmcap < m->n) { m->nrmcap = m->cap; m->nrm = (int32_t *)realloc(m->nrm, sizeof(int32_t) * 3 * (size_t)m->nrmcap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10801; }
    { const char * tb_v10802 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10802; }
    { const char * tb_v10803 = "        const double *a = m->v + 3 * m->t[3 * t], *b = m->v + 3 * m->t[3 * t + 1], *c = m->v + 3 * m->t[3 * t + 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10803; }
    { const char * tb_v10804 = "        double e1[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] }, e2[3] = { c[0] - a[0], c[1] - a[1], c[2] - a[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v10804; }
    { const char * tb_v10805 = "        double n[3] = { e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v10805; }
    { const char * tb_v10806 = "        double l = sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10806; }
    { const char * tb_v10807 = "        for (int k = 0; k < 3; k++) m->nrm[3 * t + k] = l > 1e-300 ? (int32_t)tb_rnd(n[k] / l * 16384) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10807; }
    { const char * tb_v10808 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10808; }
