    { const char * tb_v10810 = "// цвет грани под светом L (x, y, z, фон) — L уже в осях сетки; front — грань смотрит на нас\n"; *(const char * *)tb_grow(v_lines) = tb_v10810; }
    { const char * tb_v10811 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v10811; }
    { const char * tb_v10812 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10812; }
    { const char * tb_v10813 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v10813; }
    { const char * tb_v10814 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10814; }
    { const char * tb_v10815 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v10815; }
    { const char * tb_v10816 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10816; }
    { const char * tb_v10817 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v10817; }
    { const char * tb_v10818 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v10818; }
    { const char * tb_v10819 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v10819; }
    { const char * tb_v10820 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10820; }
    { const char * tb_v10821 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v10821; }
    { const char * tb_v10822 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10822; }
    { const char * tb_v10823 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v10823; }
    { const char * tb_v10824 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v10824; }
    { const char * tb_v10825 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v10825; }
    { const char * tb_v10826 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v10826; }
    { const char * tb_v10827 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v10827; }
    { const char * tb_v10828 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v10828; }
    { const char * tb_v10829 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v10829; }
    { const char * tb_v10830 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v10830; }
    { const char * tb_v10831 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v10831; }
    { const char * tb_v10832 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v10832; }
    { const char * tb_v10833 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v10833; }
    { const char * tb_v10834 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v10834; }
    { const char * tb_v10835 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v10835; }
    { const char * tb_v10836 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10836; }
    { const char * tb_v10837 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10837; }
    { const char * tb_v10838 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v10838; }
    { const char * tb_v10839 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v10839; }
    { const char * tb_v10840 = "TB_API tb_3v *tb_3vs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10840; }
