    { const char * tb_v11020 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v11020; }
    { const char * tb_v11021 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11021; }
    { const char * tb_v11022 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11022; }
    { const char * tb_v11023 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11023; }
