    { const char * tb_v11050 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11050; }
    { const char * tb_v11051 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11051; }
