    { const char * tb_v11416 = "// у угла k кость b с весом w (0 — убрать); у угла до 4 костей, лишняя вытесняет самую лёгкую\n"; *(const char * *)tb_grow(v_lines) = tb_v11416; }
    { const char * tb_v11417 = "static void tb_skin_set(tb_mesh *m, long long k, int b, double w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11417; }
