    { const char * tb_v11427 = "static long long tb_mesh_find(const tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11427; }
    { const char * tb_v11428 = "    if (!m->hcap) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11428; }
