    { const char * tb_v11435 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11435; }
    { const char * tb_v11436 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11436; }
    { const char * tb_v11437 = "// угол (x, y, z) — уже добавленный в сетку — слушается кость b с весом w (веса угла потом делятся на их сумму;\n"; *(const char * *)tb_grow(v_lines) = tb_v11437; }
