    { const char * tb_v11439 = "TB_API void tb_bone_weight(long long id, long long b, double x, double y, double z, double w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11439; }
    { const char * tb_v11440 = "    if (id < 0 || id >= tb_nmesh || b < 0 || b >= tb_meshes[id].nb) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11440; }
