    { const char * tb_v11449 = "TB_API void tb_bone_box(long long id, long long b, double x0, double y0, double z0, double x1, double y1, double z1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11449; }
    { const char * tb_v11450 = "    if (id < 0 || id >= tb_nmesh || b < 0 || b >= tb_meshes[id].nb) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11450; }
    { const char * tb_v11451 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v11451; }
