    { const char * tb_v11453 = "    tb_skin_mem(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v11453; }
    { const char * tb_v11454 = "    double lo[3] = { tb_fmin(x0, x1), tb_fmin(y0, y1), tb_fmin(z0, z1) }, hi[3] = { tb_fmax(x0, x1), tb_fmax(y0, y1), tb_fmax(z0, z1) };\n"; *(const char * *)tb_grow(v_lines) = tb_v11454; }
