    { const char * tb_v11458 = "        for (int i = 0; i < 4; i++) { m->sb[4 * k + i] = -1; m->sw[4 * k + i] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11458; }
    { const char * tb_v11459 = "        m->sb[4 * k] = (int16_t)b; m->sw[4 * k] = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11459; }
    { const char * tb_v11460 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11460; }
    { const char * tb_v11461 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11461; }
    { const char * tb_v11462 = "// где сейчас кости: для каждой — поворот (3 × 3) и сдвиг: точка p сетки уходит в G p + t\n"; *(const char * *)tb_grow(v_lines) = tb_v11462; }
    { const char * tb_v11463 = "static void tb_bones_pose(const tb_mesh *m, double *bm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11463; }
    { const char * tb_v11464 = "    for (long long b = 0; b < m->nb; b++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11464; }
