    { const char * tb_v11467 = "        tb_rot3(k->rot[0], k->rot[1], k->rot[2], R);\n"; *(const char * *)tb_grow(v_lines) = tb_v11467; }
    { const char * tb_v11468 = "        for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11468; }
    { const char * tb_v11469 = "            for (int j = 0; j < 3; j++) L[3 * i + j] = R[i][j];\n"; *(const char * *)tb_grow(v_lines) = tb_v11469; }
    { const char * tb_v11470 = "            L[9 + i] = k->piv[i] + k->mv[i] - (R[i][0] * k->piv[0] + R[i][1] * k->piv[1] + R[i][2] * k->piv[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11470; }
    { const char * tb_v11471 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11471; }
    { const char * tb_v11472 = "        double *G = bm + 12 * b;\n"; *(const char * *)tb_grow(v_lines) = tb_v11472; }
    { const char * tb_v11473 = "        if (k->parent < 0) { memcpy(G, L, sizeof L); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11473; }
    { const char * tb_v11474 = "        const double *P = bm + 12 * k->parent;\n"; *(const char * *)tb_grow(v_lines) = tb_v11474; }
