    { const char * tb_v11476 = "            for (int j = 0; j < 3; j++) G[3 * i + j] = P[3 * i] * L[j] + P[3 * i + 1] * L[3 + j] + P[3 * i + 2] * L[6 + j];\n"; *(const char * *)tb_grow(v_lines) = tb_v11476; }
    { const char * tb_v11477 = "            G[9 + i] = P[3 * i] * L[9] + P[3 * i + 1] * L[10] + P[3 * i + 2] * L[11] + P[9 + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11477; }
