    { const char * tb_v11483 = "// плавные: в каждом углу — среднее нормалей соседних треугольников, повёрнутых не больше чем на 60°\n"; *(const char * *)tb_grow(v_lines) = tb_v11483; }
    { const char * tb_v11484 = "// от своего (у куба углы остаются острыми, у шара свет течёт плавно)\n"; *(const char * *)tb_grow(v_lines) = tb_v11484; }
