    { const char * tb_v12060 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12060; }
    { const char * tb_v12061 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12061; }
    { const char * tb_v12062 = "    if (!tried) { tried = 1; dlopen(\"/System/Library/Frameworks/GameController.framework/GameController\", RTLD_LAZY); }\n"; *(const char * *)tb_grow(v_lines) = tb_v12062; }
    { const char * tb_v12063 = "    id cls = TB_CLS(\"GCController\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12063; }
    { const char * tb_v12064 = "    for (int p = 0; p < TB_PADS; p++) tb_pads[p].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12064; }
    { const char * tb_v12065 = "    if (!cls) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v12065; }
    { const char * tb_v12066 = "    id all = TB_MSG(id, cls, \"controllers\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12066; }
    { const char * tb_v12067 = "    unsigned long n = all ? TB_MSG(unsigned long, all, \"count\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12067; }
    { const char * tb_v12068 = "    for (unsigned long i = 0; i < n && i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12068; }
    { const char * tb_v12069 = "        id c = TB_MSG1(id, all, \"objectAtIndex:\", unsigned long, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v12069; }
    { const char * tb_v12070 = "        id g = TB_MSG(id, c, \"extendedGamepad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12070; }
    { const char * tb_v12071 = "        if (!g) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12071; }
    { const char * tb_v12072 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v12072; }
    { const char * tb_v12073 = "        p->on = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12073; }
    { const char * tb_v12074 = "        static const char *bn[TB_PB_N] = { \"buttonA\", \"buttonB\", \"buttonX\", \"buttonY\", \"leftShoulder\", \"rightShoulder\",\n"; *(const char * *)tb_grow(v_lines) = tb_v12074; }
    { const char * tb_v12075 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12075; }
    { const char * tb_v12076 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12076; }
    { const char * tb_v12077 = "            if (!bn[k]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12077; }
    { const char * tb_v12078 = "            if (!class_respondsToSelector(object_getClass(g), sel_getUid(bn[k]))) { p->b[k] = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12078; }
    { const char * tb_v12079 = "            id el = TB_MSG(id, g, bn[k]);\n"; *(const char * *)tb_grow(v_lines) = tb_v12079; }
    { const char * tb_v12080 = "            p->b[k] = el ? (int)TB_MSG(BOOL, el, \"isPressed\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12080; }
