    { const char * tb_v12083 = "        p->b[TB_PB_UP] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"up\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12083; }
    { const char * tb_v12084 = "        p->b[TB_PB_DOWN] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"down\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12084; }
    { const char * tb_v12085 = "        p->b[TB_PB_LEFT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"left\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12085; }
    { const char * tb_v12086 = "        p->b[TB_PB_RIGHT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"right\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12086; }
    { const char * tb_v12087 = "        id ls = TB_MSG(id, g, \"leftThumbstick\"), rs = TB_MSG(id, g, \"rightThumbstick\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12087; }
    { const char * tb_v12088 = "        p->a[TB_PA_LX] = TB_MSG(float, TB_MSG(id, ls, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12088; }
    { const char * tb_v12089 = "        p->a[TB_PA_LY] = -TB_MSG(float, TB_MSG(id, ls, \"yAxis\"), \"value\");   // у Apple вверх — плюс\n"; *(const char * *)tb_grow(v_lines) = tb_v12089; }
    { const char * tb_v12090 = "        p->a[TB_PA_RX] = TB_MSG(float, TB_MSG(id, rs, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12090; }
    { const char * tb_v12091 = "        p->a[TB_PA_RY] = -TB_MSG(float, TB_MSG(id, rs, \"yAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12091; }
    { const char * tb_v12092 = "        p->a[TB_PA_L2] = TB_MSG(float, TB_MSG(id, g, \"leftTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12092; }
    { const char * tb_v12093 = "        p->a[TB_PA_R2] = TB_MSG(float, TB_MSG(id, g, \"rightTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12093; }
    { const char * tb_v12094 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12094; }
    { const char * tb_v12095 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12095; }
    { const char * tb_v12096 = "#elif defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v12096; }
    { const char * tb_v12097 = "typedef struct { unsigned short buttons; unsigned char lt, rt; short lx, ly, rx, ry; } tb_xpad;\n"; *(const char * *)tb_grow(v_lines) = tb_v12097; }
    { const char * tb_v12098 = "typedef struct { unsigned long packet; tb_xpad pad; } tb_xstate;\n"; *(const char * *)tb_grow(v_lines) = tb_v12098; }
    { const char * tb_v12099 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12099; }
    { const char * tb_v12100 = "    static unsigned long (__stdcall *get)(unsigned long, tb_xstate *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12100; }
    { const char * tb_v12101 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12101; }
    { const char * tb_v12102 = "    if (!tried) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12102; }
    { const char * tb_v12103 = "        tried = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12103; }
    { const char * tb_v12104 = "        HMODULE h = LoadLibraryA(\"xinput1_4.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12104; }
    { const char * tb_v12105 = "        if (!h) h = LoadLibraryA(\"xinput9_1_0.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12105; }
    { const char * tb_v12106 = "        if (h) get = (unsigned long (__stdcall *)(unsigned long, tb_xstate *))GetProcAddress(h, \"XInputGetState\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12106; }
    { const char * tb_v12107 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12107; }
    { const char * tb_v12108 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12108; }
    { const char * tb_v12109 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v12109; }
    { const char * tb_v12110 = "        tb_xstate st; memset(&st, 0, sizeof st);\n"; *(const char * *)tb_grow(v_lines) = tb_v12110; }
    { const char * tb_v12111 = "        p->on = get && get((unsigned long)i, &st) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12111; }
    { const char * tb_v12112 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12112; }
    { const char * tb_v12113 = "        unsigned short w = st.pad.buttons;\n"; *(const char * *)tb_grow(v_lines) = tb_v12113; }
    { const char * tb_v12114 = "        static const unsigned short bit[TB_PB_N] = { 0x1000, 0x2000, 0x4000, 0x8000, 0x0100, 0x0200, 0, 0, 0x0040, 0x0080, 0x0010, 0x0020, 0, 0x0001, 0x0002, 0x0004, 0x0008 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12114; }
    { const char * tb_v12115 = "        for (int k = 0; k < TB_PB_N; k++) p->b[k] = bit[k] ? (w & bit[k]) != 0 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12115; }
    { const char * tb_v12116 = "        p->b[TB_PB_L2] = st.pad.lt > 30; p->b[TB_PB_R2] = st.pad.rt > 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v12116; }
    { const char * tb_v12117 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12117; }
    { const char * tb_v12118 = "        p->a[TB_PA_RX] = st.pad.rx / 32767.0; p->a[TB_PA_RY] = -st.pad.ry / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12118; }
    { const char * tb_v12119 = "        p->a[TB_PA_L2] = st.pad.lt / 255.0; p->a[TB_PA_R2] = st.pad.rt / 255.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12119; }
    { const char * tb_v12120 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12120; }
    { const char * tb_v12121 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12121; }
    { const char * tb_v12122 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v12122; }
    { const char * tb_v12123 = "#include <fcntl.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v12123; }
    { const char * tb_v12124 = "TB_API int tb_pad_fd[TB_PADS] = { -1, -1, -1, -1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12124; }
    { const char * tb_v12125 = "TB_API long long tb_pad_look = -100000;\n"; *(const char * *)tb_grow(v_lines) = tb_v12125; }
    { const char * tb_v12126 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12126; }
    { const char * tb_v12127 = "    // новые геймпады ищем раз в 2 секунды\n"; *(const char * *)tb_grow(v_lines) = tb_v12127; }
    { const char * tb_v12128 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v12128; }
