    { const char * tb_v12273 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12273; }
    { const char * tb_v12274 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v12274; }
    { const char * tb_v12275 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12275; }
    { const char * tb_v12276 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v12276; }
    { const char * tb_v12277 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v12277; }
    { const char * tb_v12278 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v12278; }
    { const char * tb_v12279 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12279; }
    { const char * tb_v12280 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v12280; }
    { const char * tb_v12281 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v12281; }
