    { const char * tb_v12284 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v12284; }
    { const char * tb_v12285 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12285; }
    { const char * tb_v12286 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12286; }
    { const char * tb_v12287 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v12287; }
    { const char * tb_v12288 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12288; }
    { const char * tb_v12289 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12289; }
