    { const char * tb_v12291 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12291; }
    { const char * tb_v12292 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12292; }
    { const char * tb_v12293 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v12293; }
    { const char * tb_v12294 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12294; }
    { const char * tb_v12295 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v12295; }
    { const char * tb_v12296 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v12296; }
    { const char * tb_v12297 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12297; }
    { const char * tb_v12298 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12298; }
    { const char * tb_v12299 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v12299; }
    { const char * tb_v12300 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v12300; }
    { const char * tb_v12301 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12301; }
    { const char * tb_v12302 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v12302; }
    { const char * tb_v12303 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v12303; }
    { const char * tb_v12304 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v12304; }
    { const char * tb_v12305 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v12305; }
    { const char * tb_v12306 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v12306; }
    { const char * tb_v12307 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v12307; }
    { const char * tb_v12308 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12308; }
    { const char * tb_v12309 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12309; }
    { const char * tb_v12310 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v12310; }
    { const char * tb_v12311 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v12311; }
    { const char * tb_v12312 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v12312; }
    { const char * tb_v12313 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v12313; }
    { const char * tb_v12314 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v12314; }
    { const char * tb_v12315 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v12315; }
    { const char * tb_v12316 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v12316; }
    { const char * tb_v12317 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12317; }
    { const char * tb_v12318 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12318; }
    { const char * tb_v12319 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v12319; }
    { const char * tb_v12320 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v12320; }
    { const char * tb_v12321 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v12321; }
    { const char * tb_v12322 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v12322; }
    { const char * tb_v12323 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12323; }
    { const char * tb_v12324 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v12324; }
    { const char * tb_v12325 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v12325; }
    { const char * tb_v12326 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12326; }
    { const char * tb_v12327 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v12327; }
    { const char * tb_v12328 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12328; }
    { const char * tb_v12329 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v12329; }
    { const char * tb_v12330 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v12330; }
    { const char * tb_v12331 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12331; }
    { const char * tb_v12332 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v12332; }
    { const char * tb_v12333 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12333; }
    { const char * tb_v12334 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v12334; }
    { const char * tb_v12335 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12335; }
    { const char * tb_v12336 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12336; }
    { const char * tb_v12337 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12337; }
    { const char * tb_v12338 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v12338; }
    { const char * tb_v12339 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12339; }
    { const char * tb_v12340 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12340; }
    { const char * tb_v12341 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v12341; }
    { const char * tb_v12342 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v12342; }
    { const char * tb_v12343 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v12343; }
    { const char * tb_v12344 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12344; }
    { const char * tb_v12345 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12345; }
    { const char * tb_v12346 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v12346; }
    { const char * tb_v12347 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12347; }
    { const char * tb_v12348 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12348; }
    { const char * tb_v12349 = "                r = tb_smono(s, v->pos - dr * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12349; }
