    { const char * tb_v12351 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v12351; }
    { const char * tb_v12352 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v12352; }
    { const char * tb_v12353 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v12353; }
    { const char * tb_v12354 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12354; }
    { const char * tb_v12355 = "                l = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12355; }
    { const char * tb_v12356 = "                r = tb_sread(s, v->pos, 1, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12356; }
    { const char * tb_v12357 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v12357; }
    { const char * tb_v12358 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12358; }
    { const char * tb_v12359 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v12359; }
    { const char * tb_v12360 = "            out[2 * i] += l * gl;\n"; *(const char * *)tb_grow(v_lines) = tb_v12360; }
    { const char * tb_v12361 = "            out[2 * i + 1] += r * gr;\n"; *(const char * *)tb_grow(v_lines) = tb_v12361; }
    { const char * tb_v12362 = "            gl += dgl; gr += dgr; dl += ddl; dr += ddr;\n"; *(const char * *)tb_grow(v_lines) = tb_v12362; }
    { const char * tb_v12363 = "            v->pos += step;\n"; *(const char * *)tb_grow(v_lines) = tb_v12363; }
    { const char * tb_v12364 = "            if (v->pos >= (double)s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12364; }
    { const char * tb_v12365 = "                if (v->loop) v->pos -= (double)s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v12365; }
    { const char * tb_v12366 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12366; }
    { const char * tb_v12367 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v12367; }
    { const char * tb_v12368 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12368; }
    { const char * tb_v12369 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v12369; }
    { const char * tb_v12370 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v12370; }
    { const char * tb_v12371 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12371; }
    { const char * tb_v12372 = "    float mt = (float)tb_master;\n"; *(const char * *)tb_grow(v_lines) = tb_v12372; }
    { const char * tb_v12373 = "    pthread_mutex_unlock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v12373; }
    { const char * tb_v12374 = "    // общая громкость (плавно) и ограничитель: громко — сразу тише, потом медленно назад\n"; *(const char * *)tb_grow(v_lines) = tb_v12374; }
    { const char * tb_v12375 = "    float dm = (mt - tb_mg) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v12375; }
    { const char * tb_v12376 = "    for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12376; }
    { const char * tb_v12377 = "        tb_mg += dm;\n"; *(const char * *)tb_grow(v_lines) = tb_v12377; }
    { const char * tb_v12378 = "        float l = out[2 * i] * tb_mg, r = out[2 * i + 1] * tb_mg;\n"; *(const char * *)tb_grow(v_lines) = tb_v12378; }
    { const char * tb_v12379 = "        float pk = fabsf(l) > fabsf(r) ? fabsf(l) : fabsf(r);\n"; *(const char * *)tb_grow(v_lines) = tb_v12379; }
    { const char * tb_v12380 = "        if (pk * tb_lim > 0.98f) tb_lim = 0.98f / pk;\n"; *(const char * *)tb_grow(v_lines) = tb_v12380; }
    { const char * tb_v12381 = "        else tb_lim += (1 - tb_lim) * 0.0002f;\n"; *(const char * *)tb_grow(v_lines) = tb_v12381; }
    { const char * tb_v12382 = "        l *= tb_lim; r *= tb_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v12382; }
    { const char * tb_v12383 = "        out[2 * i] = l > 1 ? 1 : l < -1 ? -1 : l;\n"; *(const char * *)tb_grow(v_lines) = tb_v12383; }
    { const char * tb_v12384 = "        out[2 * i + 1] = r > 1 ? 1 : r < -1 ? -1 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v12384; }
    { const char * tb_v12385 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12385; }
    { const char * tb_v12386 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12386; }
    { const char * tb_v12387 = "static long long tb_snd_now_us(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12387; }
    { const char * tb_v12388 = "    struct timespec ts;\n"; *(const char * *)tb_grow(v_lines) = tb_v12388; }
    { const char * tb_v12389 = "    clock_gettime(CLOCK_MONOTONIC, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v12389; }
    { const char * tb_v12390 = "    return (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v12390; }
    { const char * tb_v12391 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12391; }
    { const char * tb_v12392 = "// без устройства: время идёт как настоящее, звук — в файл (TB_SOUND_FILE) или никуда\n"; *(const char * *)tb_grow(v_lines) = tb_v12392; }
    { const char * tb_v12393 = "static void tb_snd_paced(FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12393; }
    { const char * tb_v12394 = "    float buf[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v12394; }
    { const char * tb_v12395 = "    short pcm[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v12395; }
    { const char * tb_v12396 = "    unsigned long long bytes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12396; }
    { const char * tb_v12397 = "    long long next = tb_snd_now_us();\n"; *(const char * *)tb_grow(v_lines) = tb_v12397; }
    { const char * tb_v12398 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12398; }
    { const char * tb_v12399 = "        tb_mix(buf, TB_SBLOCK);\n"; *(const char * *)tb_grow(v_lines) = tb_v12399; }
    { const char * tb_v12400 = "        if (f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12400; }
    { const char * tb_v12401 = "            for (int i = 0; i < TB_SBLOCK * 2; i++) pcm[i] = (short)lrintf(buf[i] * 32767);\n"; *(const char * *)tb_grow(v_lines) = tb_v12401; }
    { const char * tb_v12402 = "            fwrite(pcm, sizeof pcm, 1, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v12402; }
    { const char * tb_v12403 = "            bytes += sizeof pcm;\n"; *(const char * *)tb_grow(v_lines) = tb_v12403; }
    { const char * tb_v12404 = "            // заголовок WAV сразу верный: программа может закончиться когда угодно\n"; *(const char * *)tb_grow(v_lines) = tb_v12404; }
    { const char * tb_v12405 = "            unsigned int riff = (unsigned int)(36 + bytes), data = (unsigned int)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v12405; }
    { const char * tb_v12406 = "            fseek(f, 4, SEEK_SET); fwrite(&riff, 4, 1, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v12406; }
    { const char * tb_v12407 = "            fseek(f, 40, SEEK_SET); fwrite(&data, 4, 1, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v12407; }
    { const char * tb_v12408 = "            fseek(f, 0, SEEK_END);\n"; *(const char * *)tb_grow(v_lines) = tb_v12408; }
    { const char * tb_v12409 = "            fflush(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v12409; }
    { const char * tb_v12410 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12410; }
    { const char * tb_v12411 = "        next += 1000000LL * TB_SBLOCK / TB_SR;\n"; *(const char * *)tb_grow(v_lines) = tb_v12411; }
    { const char * tb_v12412 = "        long long wait = next - tb_snd_now_us();\n"; *(const char * *)tb_grow(v_lines) = tb_v12412; }
