    { const char * tb_v12569 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v12569; }
    { const char * tb_v12570 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12570; }
    { const char * tb_v12571 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12571; }
    { const char * tb_v12572 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12572; }
    { const char * tb_v12573 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v12573; }
    { const char * tb_v12574 = "    unsigned char *b = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12574; }
    { const char * tb_v12575 = "    if (!b || fread(b, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(b); tb_err = \"не могу прочитать файл звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12575; }
    { const char * tb_v12576 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v12576; }
    { const char * tb_v12577 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12577; }
    { const char * tb_v12578 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v12578; }
    { const char * tb_v12579 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v12579; }
    { const char * tb_v12580 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12580; }
    { const char * tb_v12581 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12581; }
    { const char * tb_v12582 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12582; }
    { const char * tb_v12583 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12583; }
    { const char * tb_v12584 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12584; }
    { const char * tb_v12585 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v12585; }
    { const char * tb_v12586 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12586; }
    { const char * tb_v12587 = "        uint32_t n = tb_le32(b + p + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v12587; }
    { const char * tb_v12588 = "        const unsigned char *c = b + p + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v12588; }
    { const char * tb_v12589 = "        if ((long)n > sz - p - 8) n = (uint32_t)(sz - p - 8);   // последний кусок обрезан — берём что есть\n"; *(const char * *)tb_grow(v_lines) = tb_v12589; }
    { const char * tb_v12590 = "        if (memcmp(b + p, \"fmt \", 4) == 0 && n >= 16) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12590; }
    { const char * tb_v12591 = "            tag = tb_le16(c); ch = tb_le16(c + 2); rate = tb_le32(c + 4); bits = tb_le16(c + 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v12591; }
    { const char * tb_v12592 = "            if (tag == 0xFFFE && n >= 26) tag = tb_le16(c + 24);   // «расширенный» WAV: вид внутри\n"; *(const char * *)tb_grow(v_lines) = tb_v12592; }
    { const char * tb_v12593 = "        } else if (memcmp(b + p, \"data\", 4) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12593; }
    { const char * tb_v12594 = "            data = c; dlen = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v12594; }
    { const char * tb_v12595 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12595; }
    { const char * tb_v12596 = "        p += 8 + (long)n + (n & 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v12596; }
    { const char * tb_v12597 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12597; }
    { const char * tb_v12598 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v12598; }
    { const char * tb_v12599 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12599; }
    { const char * tb_v12600 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v12600; }
    { const char * tb_v12601 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v12601; }
    { const char * tb_v12602 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12602; }
    { const char * tb_v12603 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12603; }
    { const char * tb_v12604 = "    uint32_t bpf = ch * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v12604; }
