    { const char * tb_v12611 = "            const unsigned char *q = data + i * bpf + (uint32_t)k * (bits / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v12611; }
    { const char * tb_v12612 = "            float v;\n"; *(const char * *)tb_grow(v_lines) = tb_v12612; }
