    { const char * tb_v12654 = "// голос по номеру (под замком); старый номер (голос уже другой) — 0\n"; *(const char * *)tb_grow(v_lines) = tb_v12654; }
    { const char * tb_v12655 = "static tb_voice *tb_voice_at(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12655; }
