    { const char * tb_v12665 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v12665; }
    { const char * tb_v12666 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12666; }
    { const char * tb_v12667 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12667; }
    { const char * tb_v12668 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v12668; }
    { const char * tb_v12669 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v12669; }
    { const char * tb_v12670 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v12670; }
    { const char * tb_v12671 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12671; }
    { const char * tb_v12672 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v12672; }
    { const char * tb_v12673 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v12673; }
    { const char * tb_v12674 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12674; }
    { const char * tb_v12675 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12675; }
