    { const char * tb_v13076 = "#   данные, переменные потока (.tdata, .tbss — образ для блока каждой задачи), .bss\n"; *(const char * *)tb_grow(v_lines) = tb_v13076; }
    { const char * tb_v13077 = "#   с границы 4 МБ: .tbheap (куча, в файл не пишется)\n"; *(const char * *)tb_grow(v_lines) = tb_v13077; }
    { const char * tb_v13078 = "# Запуск:  python3 elf_link.py вход.o -o выход.elf\n"; *(const char * *)tb_grow(v_lines) = tb_v13078; }
    { const char * tb_v13079 = "import struct\n"; *(const char * *)tb_grow(v_lines) = tb_v13079; }
    { const char * tb_v13080 = "import sys\n"; *(const char * *)tb_grow(v_lines) = tb_v13080; }
    { const char * tb_v13081 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v13081; }
